/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );

// Note: keep the following in alphabetical order according to the `require` path...
var getModify = require( './modify/get.js' );
var setModify = require( './modify/set.js' );

var getTrigger = require( './trigger/get.js' );
var setTrigger = require( './trigger/set.js' );

var getValues = require( './values/get.js' );
var setValues = require( './values/set.js' );


// VARIABLES //

var debug = logger( 'vega:trigger:main' );


// MAIN //

/**
* Trigger constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.trigger - trigger condition
* @param {string} [options.modify] - expression which returns data objects to modify
* @param {string} [options.values] - expression which returns the field values which should be updated for the data objects returned by the modify expression
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Trigger} trigger instance
*
* @example
* var trigger = new Trigger({
*     'trigger': '!shift'
* });
* // returns <Trigger>
*/
function Trigger( options ) {
	var v;
	var k;
	var i;
	if ( !( this instanceof Trigger ) ) {
		return new Trigger( options );
	}
	EventEmitter.call( this );
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	// Check for required properties...
	if ( !hasProp( options, 'trigger' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify the trigger condition.' );
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Trigger, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Trigger
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Trigger, 'name', 'Trigger' );

/**
* Expression which returns data objects to modify.
*
* @name modify
* @memberof Trigger.prototype
* @type {(string|void)}
*
* @example
* var trigger = new Trigger({
*     'trigger': '!shift',
*     'modify': 'dragged'
* });
*
* var v = trigger.modify;
* // returns 'dragged'
*/
setReadWriteAccessor( Trigger.prototype, 'modify', getModify, setModify );

/**
* Trigger name.
*
* @name trigger
* @memberof Trigger.prototype
* @type {string}
*
* @example
* var trigger = new Trigger({
*     'trigger': '!shift'
* });
*
* var v = trigger.trigger;
* // returns '!shift'
*/
setReadWriteAccessor( Trigger.prototype, 'trigger', getTrigger, setTrigger );

/**
* Expression which returns the field values which should be updated for the data objects returned by the modify expression.
*
* @name values
* @memberof Trigger.prototype
* @type {(string|void)}
*
* @example
* var trigger = new Trigger({
*     'trigger': '!shift',
*     'values': '{fx: x(), fy: y()}'
* });
*
* var v = trigger.values;
* // returns '{fx: x(), fy: y()}'
*/
setReadWriteAccessor( Trigger.prototype, 'values', getValues, setValues );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Trigger.prototype
* @type {Function}
* @throws {Error} invalid configuration
* @returns {Object} JSON object
*
* @example
* var trigger = new Trigger({
*     'trigger': '!shift'
* });
*
* var v = trigger.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Trigger.prototype, 'toJSON', function toJSON() {
	if ( this._modify && !this._values ) {
		throw new Error( 'invalid operation. Current configuration is invalid. A trigger having a `modify` expression must also have a `values` expression.' );
	}
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Trigger;
